package goprotoc

import (
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
)

// pluginNamePrefix is the conventional prefix of a protoc plugin's name, which
// is followed by the output language the plugin generates.
const pluginNamePrefix = "protoc-gen-"

// pluginLang returns the output language generated by the plugin with the given
// name, reporting whether the name follows the plugin naming convention.
func pluginLang(name string) (string, bool) {
	if !strings.HasPrefix(name, pluginNamePrefix) {
		return "", false
	}
	return name[len(pluginNamePrefix):], true
}

// pluginExeName returns the conventional name of the plugin that generates the
// given output language.
func pluginExeName(lang string) string {
	return pluginNamePrefix + lang
}

type pluginKind int

const (
	// pluginKindExec means the plugin location is the path of an executable.
	pluginKindExec pluginKind = iota
	// pluginKindGoTool means the plugin location is a Go package path that is
	// run via "go tool".
	pluginKindGoTool
)

// pluginDef indicates how a single plugin is to be located and run.
type pluginDef struct {
	kind pluginKind
	loc  string
}

type protocOptions struct {
	includePaths          []string
	encodeType            string
	decodeType            string
	decodeRaw             bool
	inputDescriptors      []string
	outputDescriptor      string
	includeImports        bool
	includeSourceInfo     bool
	printFreeFieldNumbers bool
	pluginDefs            map[string]pluginDef
	output                map[string]string
	protoFiles            []string
}

func parseFlags(source string, programName string, args []string, stdout io.Writer, opts *protocOptions, sourcesSeen map[string]struct{}) error {
	if _, ok := sourcesSeen[source]; ok {
		return fmt.Errorf("cycle detected in option files: %s references itself (possibly indirectly)", source)
	}
	sourcesSeen[source] = struct{}{}

	for i := 0; i < len(args); i++ {
		loc := func() string {
			if source == "" {
				return ""
			}
			return fmt.Sprintf("%s:%d: ", source, i+1)
		}

		a := args[i]
		if a == "--" {
			opts.protoFiles = append(opts.protoFiles, args[i+1:]...)
			break
		}
		if !strings.HasPrefix(a, "-") {
			opts.protoFiles = append(opts.protoFiles, a)
			continue
		}
		parts := strings.SplitN(args[i], "=", 2)

		getOptionArg := func() (string, error) {
			if len(parts) > 1 {
				return parts[1], nil
			}
			if len(args) > i+1 {
				i++
				return args[i], nil
			}
			return "", fmt.Errorf("%sMissing value for flag: %s", loc(), parts[0])
		}
		getBoolArg := func() (bool, error) {
			if len(parts) > 1 {
				val := strings.ToLower(parts[1])
				switch val {
				case "true":
					return true, nil
				case "false":
					return false, nil
				default:
					return false, fmt.Errorf("%svalue for option %s must be 'true' or 'false'", loc(), parts[0])
				}
			}
			return true, nil
		}
		noOptionArg := func() error {
			if len(parts) > 1 {
				return fmt.Errorf("%s%s does not take a parameter", loc(), parts[0])
			}
			return nil
		}

		switch parts[0] {
		case "-I", "--proto_path":
			value, err := getOptionArg()
			if err != nil {
				return err
			}
			opts.includePaths = append(opts.includePaths, value)
		case "--version":
			if err := noOptionArg(); err != nil {
				return err
			}
			if _, err := fmt.Fprintf(stdout, "goprotoc %s (proto %s)\n", version, protocVersionEmu); err != nil {
				return err
			}
			return errVersion
		case "-h", "--help":
			if err := noOptionArg(); err != nil {
				return err
			}
			if err := usage(programName, stdout); err != nil {
				return err
			}
			return errUsage
		case "--encode":
			value, err := getOptionArg()
			if err != nil {
				return err
			}
			opts.encodeType = value
		case "--decode":
			value, err := getOptionArg()
			if err != nil {
				return err
			}
			opts.decodeType = value
		case "--decode_raw":
			value, err := getBoolArg()
			if err != nil {
				return err
			}
			opts.decodeRaw = value
		case "--descriptor_set_in":
			value, err := getOptionArg()
			if err != nil {
				return err
			}
			opts.inputDescriptors = append(opts.inputDescriptors, value)
		case "-o", "--descriptor_set_out":
			value, err := getOptionArg()
			if err != nil {
				return err
			}
			opts.outputDescriptor = value
		case "--include_imports":
			value, err := getBoolArg()
			if err != nil {
				return err
			}
			opts.includeImports = value
		case "--include_source_info":
			value, err := getBoolArg()
			if err != nil {
				return err
			}
			opts.includeSourceInfo = value
		case "--print_free_field_numbers":
			value, err := getBoolArg()
			if err != nil {
				return err
			}
			opts.printFreeFieldNumbers = value
		case "--plugin":
			value, err := getOptionArg()
			if err != nil {
				return err
			}
			lang, def, err := parsePluginDef(value)
			if err != nil {
				return fmt.Errorf("%s%v", loc(), err)
			}
			if opts.pluginDefs == nil {
				opts.pluginDefs = make(map[string]pluginDef, 1)
			}
			opts.pluginDefs[lang] = def
		default:
			switch {
			case strings.HasPrefix(a, "@"):
				if err := noOptionArg(); err != nil {
					return err
				}
				source := a[1:]
				contents, err := os.ReadFile(source)
				if err != nil {
					return fmt.Errorf("%scould not load option file %s: %v", loc(), source, err)
				}
				lines := strings.Split(string(contents), "\n")
				for i := range lines {
					lines[i] = strings.TrimSpace(lines[i])
				}
				if err := parseFlags(a[1:], programName, lines, stdout, opts, sourcesSeen); err != nil {
					return err
				}
			case strings.HasPrefix(parts[0], "--") && strings.HasSuffix(parts[0], "_out"):
				value, err := getOptionArg()
				if err != nil {
					return err
				}
				if opts.output == nil {
					opts.output = make(map[string]string, 1)
				}
				opts.output[parts[0][2:len(parts[0])-4]] = value
			default:
				return fmt.Errorf("%sunrecognized option: %s", loc(), parts[0])
			}
		}
	}
	return nil
}

// parsePluginDef parses the value of a --plugin flag, which is a plugin
// location optionally preceded by "NAME=". It returns the output language the
// plugin generates and how to run it. When no name is given, it is derived from
// the location.
func parsePluginDef(value string) (string, pluginDef, error) {
	name, location := "", value
	if parts := strings.SplitN(value, "=", 2); len(parts) == 2 {
		name, location = parts[0], parts[1]
	}

	def := pluginDef{kind: pluginKindExec, loc: location}
	defaultName := filepath.Base(location)
	if pkg, ok := trimGoToolScheme(location); ok {
		if err := checkGoToolPackage(pkg); err != nil {
			return "", pluginDef{}, err
		}
		def = pluginDef{kind: pluginKindGoTool, loc: pkg}
		defaultName = goToolBaseName(pkg)
	} else if location == "" {
		return "", pluginDef{}, fmt.Errorf("plugin %s has an empty location", name)
	}
	if name == "" {
		name = defaultName
	}

	lang, ok := pluginLang(name)
	if !ok {
		return "", pluginDef{}, fmt.Errorf("plugin name %s is not valid: name should have %q prefix", name, pluginNamePrefix)
	}
	return lang, def, nil
}
